from PIL import Image
from io import BytesIO
from base64 import b64decode
import cv2
import numpy as np

# Paradigm logo data (transparent background)
logo = Image.open(BytesIO(b64decode("")))

def add_logo(picture, pos=(20, 20)):
    # Convert opencv's BRG img to PIL's RGB
    picture = cv2.cvtColor(picture, cv2.COLOR_BGR2RGB)
    picture = Image.fromarray(picture).convert("RGB")

    # Convert logo to RGBA (keeps transparency)
    logo_final = logo.convert("RGBA")

    # Add logo to picture
    picture.paste(logo_final, pos, logo_final)

    # Convert RGB back to BRG
    picture = cv2.cvtColor(np.array(picture), cv2.COLOR_RGB2BGR)

    return picture


